INSERT INTO ressource (id, genre, section, nom, nom_cle, description, prix_brut, prix_rf, page_id, ordre, origine, source_ref) VALUES ('ressources/armures#materiau:acier', 'materiau', NULL, 'Acier', 'acier', 'Utilise le minerai de fer avec un charbon de meilleur qualité et un fourneau plus chaud pour obtenir l''acier, un métal bien meilleur.', '2 000 RF / 20 RO', 2000, 'ressources/armures', 9, 'equipement', 'Ressources et Craft › Armures › A44:Y45 ; Ressources et Craft › Bouclier › K19:AI20');
INSERT INTO ressource (id, genre, section, nom, nom_cle, description, prix_brut, prix_rf, page_id, ordre, origine, source_ref) VALUES ('ressources/armures#materiau:argent', 'materiau', NULL, 'Argent', 'argent', 'Un minerai gris brillant plus rare que le fer, plus solide.', '3 500 RF / 35 RO', 3500, 'ressources/armures', 15, 'equipement', 'Ressources et Craft › Armures › A56:Y57 ; Ressources et Craft › Bouclier › K31:AI32');
INSERT INTO ressource (id, genre, section, nom, nom_cle, description, prix_brut, prix_rf, page_id, ordre, origine, source_ref) VALUES ('ressources/armures#materiau:bois', 'materiau', NULL, 'Bois', 'bois', 'Bois issue d''un arbre spécifique ou alors des créatures faites de ce même  bois.', '150 RF / 1,5 RO', 150, 'ressources/armures', 3, 'equipement', 'Ressources et Craft › Armures › A32:Y33 ; Ressources et Craft › Bouclier › K7:AI8');
INSERT INTO ressource (id, genre, section, nom, nom_cle, description, prix_brut, prix_rf, page_id, ordre, origine, source_ref) VALUES ('ressources/armures#materiau:bronze', 'materiau', NULL, 'Bronze', 'bronze', 'Combinaison du cuivre et de l''étain, le bronze est apprécié pour sa défense magique et physique correct, mais surtout pour sa solidité qui égale le titane et le maverium.', '8 500 RF / 85 RO', 8500, 'ressources/armures', 17, 'equipement', 'Ressources et Craft › Armures › A60:Y61 ; Ressources et Craft › Bouclier › K35:AI36');
INSERT INTO ressource (id, genre, section, nom, nom_cle, description, prix_brut, prix_rf, page_id, ordre, origine, source_ref) VALUES ('ressources/armures#materiau:cellulose', 'materiau', NULL, 'Cellulose', 'cellulose', 'Cette matière ressemble beaucoup à du papier, elle ne protège pas des ocups physique mais très bien de la magie.', '600 RF / 6 RO', 600, 'ressources/armures', 4, 'equipement', 'Ressources et Craft › Armures › A34:Y35 ; Ressources et Craft › Bouclier › K9:AI10');
INSERT INTO ressource (id, genre, section, nom, nom_cle, description, prix_brut, prix_rf, page_id, ordre, origine, source_ref) VALUES ('ressources/armures#materiau:chitine', 'materiau', NULL, 'Chitine', 'chitine', 'Matière qu''on retoruve sur les insectes ou autre arachnide principalement, très solide.', '1 500 RF / 15 RO', 1500, 'ressources/armures', 6, 'equipement', 'Ressources et Craft › Armures › A38:Y39 ; Ressources et Craft › Bouclier › K13:AI14');
INSERT INTO ressource (id, genre, section, nom, nom_cle, description, prix_brut, prix_rf, page_id, ordre, origine, source_ref) VALUES ('ressources/armures#materiau:corail', 'materiau', NULL, 'Corail', 'corail', 'Matiére solide et qui a un effet contre la magie, on le trouve dans la nature mais aussi sur les monstres faits de coraux.', '1 000 RF / 10 RO', 1000, 'ressources/armures', 5, 'equipement', 'Ressources et Craft › Armures › A36:Y37 ; Ressources et Craft › Bouclier › K11:AI12');
INSERT INTO ressource (id, genre, section, nom, nom_cle, description, prix_brut, prix_rf, page_id, ordre, origine, source_ref) VALUES ('ressources/armures#materiau:corne-os', 'materiau', NULL, 'Corne/Os', 'corne-os', 'Matière similaire à l''os, très solide permet de faire de bonne armure.', '3 000 RF / 30 RO', 3000, 'ressources/armures', 11, 'equipement', 'Ressources et Craft › Armures › A48:Y49 ; Ressources et Craft › Bouclier › K23:AI24');
INSERT INTO ressource (id, genre, section, nom, nom_cle, description, prix_brut, prix_rf, page_id, ordre, origine, source_ref) VALUES ('ressources/armures#materiau:cuir', 'materiau', NULL, 'Cuir', 'cuir', 'Une matière assez solide et très légère qui est issue de la peau animal, une sorte de peau raffiné et traité.', '200 RF / 2 RO', 200, 'ressources/armures', 2, 'equipement', 'Ressources et Craft › Armures › A30:Y31 ; Ressources et Craft › Bouclier › K5:AI6');
INSERT INTO ressource (id, genre, section, nom, nom_cle, description, prix_brut, prix_rf, page_id, ordre, origine, source_ref) VALUES ('ressources/armures#materiau:cuivre', 'materiau', NULL, 'Cuivre', 'cuivre', 'Un beau minerai couleur orangé, plus rareque le fer et plus utilisé pour autre chose que le militaire', '4 000 RF / 40 RO', 4000, 'ressources/armures', 12, 'equipement', 'Ressources et Craft › Armures › A50:Y51 ; Ressources et Craft › Bouclier › K25:AI26');
INSERT INTO ressource (id, genre, section, nom, nom_cle, description, prix_brut, prix_rf, page_id, ordre, origine, source_ref) VALUES ('ressources/armures#materiau:ecailles', 'materiau', NULL, 'Ecailles', 'ecailles', 'Un morceau de peau très solide disponible uniquement sur les créatures type reptilienne ou draconique.', '8 000 RF / 80 RO', 8000, 'ressources/armures', 13, 'equipement', 'Ressources et Craft › Armures › A52:Y53 ; Ressources et Craft › Bouclier › K27:AI28');
INSERT INTO ressource (id, genre, section, nom, nom_cle, description, prix_brut, prix_rf, page_id, ordre, origine, source_ref) VALUES ('ressources/armures#materiau:fer', 'materiau', NULL, 'Fer', 'fer', 'Minerai très commun, il suffit de prendre de pioche et de chercher.', '1 000 RF / 10 RO', 1000, 'ressources/armures', 8, 'equipement', 'Ressources et Craft › Armures › A42:Y43 ; Ressources et Craft › Bouclier › K17:AI18');
INSERT INTO ressource (id, genre, section, nom, nom_cle, description, prix_brut, prix_rf, page_id, ordre, origine, source_ref) VALUES ('ressources/armures#materiau:fer-noir', 'materiau', NULL, 'Fer noir', 'fer-noir', 'Un variante du fer, ce minerais a été exposer très longtemps à de la corruption et il s''en est impréniée, ce minerai totalement inerte est plus solide que le fer.', '3 500 RF / 35 RO', 3500, 'ressources/armures', 10, 'equipement', 'Ressources et Craft › Armures › A46:Y47 ; Ressources et Craft › Bouclier › K21:AI22');
INSERT INTO ressource (id, genre, section, nom, nom_cle, description, prix_brut, prix_rf, page_id, ordre, origine, source_ref) VALUES ('ressources/armures#materiau:fonte', 'materiau', NULL, 'Fonte', 'fonte', 'Matériaux aussi dur que fragile, il se frabrique de la même façon que l''acier mais avec moins de chaleur.', '4 000 RF / 40 RO', 4000, 'ressources/armures', 16, 'equipement', 'Ressources et Craft › Armures › A58:Y59 ; Ressources et Craft › Bouclier › K33:AI34');
INSERT INTO ressource (id, genre, section, nom, nom_cle, description, prix_brut, prix_rf, page_id, ordre, origine, source_ref) VALUES ('ressources/armures#materiau:laiton', 'materiau', NULL, 'Laiton', 'laiton', 'Combinaison du cuivre et du zinc, le laiton est nommé l''or rose par certains, il est moins solide physiquement parlant que l''or mais il encaisse bien mieux la magie.', '9 000 RF / 90 RO', 9000, 'ressources/armures', 18, 'equipement', 'Ressources et Craft › Armures › A62:Y63 ; Ressources et Craft › Bouclier › K37:AI38');
INSERT INTO ressource (id, genre, section, nom, nom_cle, description, prix_brut, prix_rf, page_id, ordre, origine, source_ref) VALUES ('ressources/armures#materiau:maverium', 'materiau', NULL, 'Maverium', 'maverium', 'Le minerai ultime de Maverick, c''est un minerai qui réagit parfaitement à la magie selon comment il est travaillé. Soit un conducteur parfait, soit un isolant parfait.', '400 RO', 40000, 'ressources/armures', 21, 'equipement', 'Ressources et Craft › Armures › A68:Y69 ; Ressources et Craft › Bouclier › K43:AI44');
INSERT INTO ressource (id, genre, section, nom, nom_cle, description, prix_brut, prix_rf, page_id, ordre, origine, source_ref) VALUES ('ressources/armures#materiau:mythril', 'materiau', NULL, 'Mythril', 'mythril', 'D''après la légende, il s''agit d''un minerais qui pousse comme un arbre au milieu de la roche elle même.', '200 RO', 20000, 'ressources/armures', 7, 'equipement', 'Ressources et Craft › Armures › A40:Y41 ; Ressources et Craft › Bouclier › K15:AI16');
INSERT INTO ressource (id, genre, section, nom, nom_cle, description, prix_brut, prix_rf, page_id, ordre, origine, source_ref) VALUES ('ressources/armures#materiau:or', 'materiau', NULL, 'Or', 'or', 'Un minerai jaune qui est utilisé pour fabriqué la monnaie du monde, cette utilisation massif de l''or la rend rare pour les autres objets.', '100 RO', 10000, 'ressources/armures', 19, 'equipement', 'Ressources et Craft › Armures › A64:Y65 ; Ressources et Craft › Bouclier › K39:AI40');
INSERT INTO ressource (id, genre, section, nom, nom_cle, description, prix_brut, prix_rf, page_id, ordre, origine, source_ref) VALUES ('ressources/armures#materiau:peau', 'materiau', NULL, 'Peau', 'peau', 'Une peau raffinée pour être utile au combat.', '100 RF / 1 RO', 100, 'ressources/armures', 1, 'equipement', 'Ressources et Craft › Armures › A28:Y29 ; Ressources et Craft › Bouclier › K3:AI4');
INSERT INTO ressource (id, genre, section, nom, nom_cle, description, prix_brut, prix_rf, page_id, ordre, origine, source_ref) VALUES ('ressources/armures#materiau:titane', 'materiau', NULL, 'Titane', 'titane', 'Le titane est un minerai gris clair aussi lourd que solide, il est assez rare et demande un fourneau de séraphin pour être travailler.', '200 RO', 20000, 'ressources/armures', 20, 'equipement', 'Ressources et Craft › Armures › A66:Y67 ; Ressources et Craft › Bouclier › K41:AI42');
INSERT INTO ressource (id, genre, section, nom, nom_cle, description, prix_brut, prix_rf, page_id, ordre, origine, source_ref) VALUES ('ressources/armures#materiau:vif-argent', 'materiau', NULL, 'Vif argent', 'vif-argent', 'La combinaison du Mythril et de l''Argent, il s''agit d''un gisement d''argent qui s''est fait perforer par du mythril et de ce mariage a donner un gisement d''argent très particulier.', '300 RO', 30000, 'ressources/armures', 14, 'equipement', 'Ressources et Craft › Armures › A54:Y55 ; Ressources et Craft › Bouclier › K29:AI30');
