INSERT INTO ressource (id, genre, section, nom, nom_cle, description, prix_brut, prix_rf, page_id, ordre, origine, source_ref) VALUES ('ressources/baton-magique#bois:bambou', 'bois', NULL, 'Bambou', 'bambou', 'C''est une herbe qui monte très haut et qui est très léger.', '1 800 RF / 18 RO', 1800, 'ressources/baton-magique', 11, 'equipement', 'Ressources et Craft › Bâton magique › AC24:BS25');
INSERT INTO ressource (id, genre, section, nom, nom_cle, description, prix_brut, prix_rf, page_id, ordre, origine, source_ref) VALUES ('ressources/baton-magique#bois:bouleau-impur', 'bois', NULL, 'Bouleau impur', 'bouleau-impur', 'La version corrompu du bouleau, ce bouleau respire la corruption et est capable de la transmettre a tout créatures assez folle pour s''approcher.', '6 000 RF / 60 RO', 6000, 'ressources/baton-magique', 3, 'equipement', 'Ressources et Craft › Bâton magique › AC8:BS9');
INSERT INTO ressource (id, genre, section, nom, nom_cle, description, prix_brut, prix_rf, page_id, ordre, origine, source_ref) VALUES ('ressources/baton-magique#bois:bouleau-pur', 'bois', NULL, 'Bouleau pur', 'bouleau-pur', 'Ce bel arbre au tronc blanc est un arbre qui attire le chakra à l''état pur, il y a souvent des brume de chakra qui se forme autour d''eux.', '1 200 RF / 12 RO', 1200, 'ressources/baton-magique', 2, 'equipement', 'Ressources et Craft › Bâton magique › AC6:BS7');
INSERT INTO ressource (id, genre, section, nom, nom_cle, description, prix_brut, prix_rf, page_id, ordre, origine, source_ref) VALUES ('ressources/baton-magique#bois:chene', 'bois', NULL, 'Chêne', 'chene', 'C''est un magnifique arbre très noble qui est capable de vivre très longtemps si il est dans d''excellente conditions, il est à l''épreuve du temps et de l''espace.', '4 400 RF / 44 RO', 4400, 'ressources/baton-magique', 4, 'equipement', 'Ressources et Craft › Bâton magique › AC10:BS11');
INSERT INTO ressource (id, genre, section, nom, nom_cle, description, prix_brut, prix_rf, page_id, ordre, origine, source_ref) VALUES ('ressources/baton-magique#bois:frene', 'bois', NULL, 'Frène', 'frene', 'Un arbre très grand qui est capable de réssiter à l''impact d''un éclair un et semble pouvoir garder la foudre en lui pour se protéger.', '1 800 RF / 18 RO', 1800, 'ressources/baton-magique', 12, 'equipement', 'Ressources et Craft › Bâton magique › AC26:BS27');
INSERT INTO ressource (id, genre, section, nom, nom_cle, description, prix_brut, prix_rf, page_id, ordre, origine, source_ref) VALUES ('ressources/baton-magique#bois:fungus-fantome', 'bois', NULL, 'Fungus Fantôme', 'fungus-fantome', 'C''est un champignon qui parasite les autres arbres, ainsi impreniant l''arbre d''une sorte d''anti-magie qui s''approche de la magie du vide.', '2 000 RF / 20 RO', 2000, 'ressources/baton-magique', 5, 'equipement', 'Ressources et Craft › Bâton magique › AC12:BS13');
INSERT INTO ressource (id, genre, section, nom, nom_cle, description, prix_brut, prix_rf, page_id, ordre, origine, source_ref) VALUES ('ressources/baton-magique#bois:khejri', 'bois', NULL, 'Khejri', 'khejri', 'Cet arbre sec se retrouve dans les zones désertiques et aride de Maverick, il est très chaud et est capable de cracher du feu quand il se sent menacer.', '2 400 RF / 24 RO', 2400, 'ressources/baton-magique', 7, 'equipement', 'Ressources et Craft › Bâton magique › AC16:BS17');
INSERT INTO ressource (id, genre, section, nom, nom_cle, description, prix_brut, prix_rf, page_id, ordre, origine, source_ref) VALUES ('ressources/baton-magique#bois:mancelinier', 'bois', NULL, 'Mancelinier', 'mancelinier', 'Cet arbre est très toxique, tellement toxique qu ''il empoisonne même l''air autour de lui, seul ceux de la nécromancie sont protéger de son air putride.', '2 000 RF / 20 RO', 2000, 'ressources/baton-magique', 6, 'equipement', 'Ressources et Craft › Bâton magique › AC14:BS15');
INSERT INTO ressource (id, genre, section, nom, nom_cle, description, prix_brut, prix_rf, page_id, ordre, origine, source_ref) VALUES ('ressources/baton-magique#bois:orme', 'bois', NULL, 'Orme', 'orme', 'Cet gigantesque arbre magestueux est assez rare, il peut mesurer jusqu''a 50 mètres de haut.', '3 000 RF / 30 RO', 3000, 'ressources/baton-magique', 10, 'equipement', 'Ressources et Craft › Bâton magique › AC22:BS23');
INSERT INTO ressource (id, genre, section, nom, nom_cle, description, prix_brut, prix_rf, page_id, ordre, origine, source_ref) VALUES ('ressources/baton-magique#bois:padouk', 'bois', NULL, 'Padouk', 'padouk', 'Cet arbre unique au tronc rouge pousse pas loin des champs de batailles, là où le sang à envahis le sol.', '2 400 RF / 24 RO', 2400, 'ressources/baton-magique', 1, 'equipement', 'Ressources et Craft › Bâton magique › AC4:BS5');
INSERT INTO ressource (id, genre, section, nom, nom_cle, description, prix_brut, prix_rf, page_id, ordre, origine, source_ref) VALUES ('ressources/baton-magique#bois:paletuvier', 'bois', NULL, 'Palétuvier', 'paletuvier', 'Un arbre parfaitement adapter à l''environnement marécageux, ses racines sont visible à la surface contrairement aux autres arbres.', '1 200 RF / 12 RO', 1200, 'ressources/baton-magique', 8, 'equipement', 'Ressources et Craft › Bâton magique › AC18:BS19');
INSERT INTO ressource (id, genre, section, nom, nom_cle, description, prix_brut, prix_rf, page_id, ordre, origine, source_ref) VALUES ('ressources/baton-magique#bois:palmier', 'bois', NULL, 'Palmier', 'palmier', 'Cet arbre tordu des places aime beaucoup le soleil et peut parfois en émètre quand la nuit arrive, comme des lampadaires.', '3 600 RF / 36 RO', 3600, 'ressources/baton-magique', 14, 'equipement', 'Ressources et Craft › Bâton magique › AC30:BS31');
INSERT INTO ressource (id, genre, section, nom, nom_cle, description, prix_brut, prix_rf, page_id, ordre, origine, source_ref) VALUES ('ressources/baton-magique#bois:sapin', 'bois', NULL, 'Sapin', 'sapin', 'Le sapin est un très grand arbre qui est parfaitement adapté aux températures très basse, il fabrique des couche de glace quand son écorce est percée.', '2 400 RF / 24 RO', 2400, 'ressources/baton-magique', 9, 'equipement', 'Ressources et Craft › Bâton magique › AC20:BS21');
INSERT INTO ressource (id, genre, section, nom, nom_cle, description, prix_brut, prix_rf, page_id, ordre, origine, source_ref) VALUES ('ressources/baton-magique#bois:saule', 'bois', NULL, 'Saule', 'saule', 'Cet arbre protège parfaitement bien du soleil et cache tout ce qu''il y a en dessous de ses feuilles et à son pied ... prudence  ...', '3 600 RF / 36 RO', 3600, 'ressources/baton-magique', 13, 'equipement', 'Ressources et Craft › Bâton magique › AC28:BS29');
INSERT INTO ressource (id, genre, section, nom, nom_cle, description, prix_brut, prix_rf, page_id, ordre, origine, source_ref) VALUES ('ressources/baton-magique#gemme:ambre', 'gemme', NULL, 'Ambre', 'ambre', 'L''ambre est la gemme qui proviens du vivant, il s''agit d''une résine ancienne qui concentre la puissance de la terre. On le trouve près de très vieux arbres.', NULL, NULL, 'ressources/baton-magique', 10, 'equipement', 'Ressources et Craft › Bâton magique › AC22:BS23');
INSERT INTO ressource (id, genre, section, nom, nom_cle, description, prix_brut, prix_rf, page_id, ordre, origine, source_ref) VALUES ('ressources/baton-magique#gemme:amethyste', 'gemme', NULL, 'Améthyste', 'amethyste', 'Dans les plus obscure grottes, il existe une magnifique pierre d''un somptueux violet qui concentre la puissance de l''obscurité.', NULL, NULL, 'ressources/baton-magique', 13, 'equipement', 'Ressources et Craft › Bâton magique › AC28:BS29');
INSERT INTO ressource (id, genre, section, nom, nom_cle, description, prix_brut, prix_rf, page_id, ordre, origine, source_ref) VALUES ('ressources/baton-magique#gemme:diamant-rose', 'gemme', NULL, 'Diamant rose', 'diamant-rose', 'Un diamant parfaitement taillé couleur rose, la gemme du temps et de l''espace.', NULL, NULL, 'ressources/baton-magique', 4, 'equipement', 'Ressources et Craft › Bâton magique › AC10:BS11');
INSERT INTO ressource (id, genre, section, nom, nom_cle, description, prix_brut, prix_rf, page_id, ordre, origine, source_ref) VALUES ('ressources/baton-magique#gemme:emeraude', 'gemme', NULL, 'Émeraude', 'emeraude', 'Avec son vert sexy, cette gemme concentre la puissance du vent, elle est très légère et se retrouve dans les plus haut sommet.', NULL, NULL, 'ressources/baton-magique', 11, 'equipement', 'Ressources et Craft › Bâton magique › AC24:BS25');
INSERT INTO ressource (id, genre, section, nom, nom_cle, description, prix_brut, prix_rf, page_id, ordre, origine, source_ref) VALUES ('ressources/baton-magique#gemme:grenat', 'gemme', NULL, 'Grenat', 'grenat', 'Une pierre rouge marron comme le sang.', NULL, NULL, 'ressources/baton-magique', 1, 'equipement', 'Ressources et Craft › Bâton magique › AC4:BS5');
